class Claim(BaseModel):
    """
    One atomic statement with provenance and two time axes.
    """

    id: ClaimId
    tenant_id: TenantId
    space_id: SpaceId
    statement: str
    """
    The claim as one self-contained sentence, conditions included.
    """
    language: Locale | None = None
    claim_type: ClaimType
    knowledge_class: KnowledgeClass
    subject_entity_id: EntityId | None = None
    subject_text: str | None = None
    """
    Subject as written, when it is not resolved to an entity yet.
    """
    predicate: Annotated[str | None, Field(pattern="^[a-z][a-z0-9_]*(\\.[a-z][a-z0-9_]*)*$")] = None
    """
    Optional normalized predicate, for example "hotel_cap_per_night".
    """
    object_entity_id: EntityId | None = None
    value: ClaimValue | None = None
    qualifiers: list[str] | None = None
    """
    Conditions, scopes and exceptions that must travel with the claim ("for tier-one cities", "except during trade fairs"). Atomizing must not drop them.

    """
    valid_time: Interval
    """
    When the statement is true in the world ("true when").
    """
    recorded_at: Instant
    """
    When the system learned it ("known when", start).
    """
    superseded_at: Instant | None = None
    """
    When the system stopped believing it ("known when", end).
    """
    superseded_by: ClaimId | None = None
    confidence: Score01
    """
    Confidence in the extraction.
    """
    authority: Score01
    """
    Trust in the best supporting source.
    """
    weight: Annotated[float, Field(ge=0.0)]
    """
    Ranking weight from authority, approval state, recency and corroboration.
    """
    status: ClaimStatus
    origin: ClaimOrigin
    owner_id: PrincipalId | None = None
    sensitivity: SensitivityLabel
    producer: ProducerInfo | None = None
    inputs_hash: ContentHash
    review_due: Instant | None = None
    created_at: Instant | None = None
    updated_at: Instant | None = None


