class PageDiff(BaseModel):
    """
    What changed between two versions, for "what changed since you last read".
    """

    page_id: PageId
    from_version: Annotated[int, Field(ge=1)]
    to_version: Annotated[int, Field(ge=1)]
    summary: str | None = None
    changes: list[BlockChange]


class PageSnapshot(BaseModel):
    """
    An immutable copy of one page version. LLM regeneration cannot reproduce an old page, so every rendered version is stored. Restoring an old version writes a new version whose blocks are pinned as overrides.

    """

    page_id: PageId
    version: Annotated[int, Field(ge=1)]
    spec: PageSpec
    cause: SnapshotCause
    change_summary: str | None = None
    """
    One-line, human-readable summary of what changed.
    """
    created_at: Instant


class PageSpec(BaseModel):
    page_id: PageId
    tenant_id: TenantId
    space_id: SpaceId
    version: Annotated[int, Field(ge=1)]
    """
    Increases by one each time the rendered content changes.
    """
    inputs_hash: ContentHash
    """
    From the freshness engine. Same inputs, same hash, no re-render.
    """
    title: str
    summary: str | None = None
    """
    One or two sentences, used in outlines and search cards.
    """
    kind: PageKind
    taxonomy_key: str | None = None
    """
    Stable key of the page's node in the document tree.
    """
    locale: Locale
    sensitivity: SensitivityLabel
    """
    The highest label among the page's sources.
    """
    blocks: list[Block]
    renderer: ProducerInfo
    rendered_at: Instant


class ViewBlock(BaseModel):
    key: BlockKey
    type: Literal["view"] = "view"
    origin: BlockOrigin | None = None
    override_id: OverrideId | None = None
    view_id: ViewId
    view_version: str
    data: DataRef
    fallback: Block
    """
    Static block (usually a table or a chart) shown until the view version is approved, and in export, print and clients that cannot run views. Never a view.

    """
    height_hint: Annotated[int | None, Field(ge=80, le=4000)] = None
    claim_ids: list[ClaimId] | None = None


